#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long a[100005];
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    long long target; scanf("%lld", &target);
    int idx = -1;
    for (int i = 0; i < n; i++) if (a[i] == target) { idx = i; break; }
    printf("%d\n", idx);
    return 0;
}

