function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (!toks || toks.length === 0 || toks[0] === "") return;
    const n = parseInt(toks[0], 10);
    const target = toks[n + 1];
    let idx = -1;
    for (let i = 1; i <= n; i++) if (toks[i] === target) { idx = i - 1; break; }
    console.log(idx);
}
main();

